-- QuestWeapons.lua: the Plan tab's "Weapon:" lines.
--
-- A step gets a weapon line when a weapon you could use drops or is rewarded there AND is better than what you wear in that slot:
--   * quest rewards: QuestWeaponData.lua (Wowhead Forever's item lists, generated by bis/build_quest_weapons.py), matched to a
--     step by the quest's zone in the step's TITLE and the step's level range (the reward's required level must be reached by
--     the end of the step). Steps that only collect quests ("collect ...") get none: the reward comes at the clear.
--   * Mr.BiZ's own weapon picks from dungeons and vendors (BiZ.RouteWeapons, matched by dungeon / vendor zone).
-- "Better" is the BiZ score (GearScore, your own spec's stat weights) against the item worn in that slot; an empty slot
-- counts as 0 (GS.Compare). Only the best weapon per slot (main hand, off hand, ranged) is shown on a step, and none that
-- is not an upgrade. An item the game has not loaded yet is asked for and shown once its stats arrive (the Plan tab
-- redraws on GET_ITEM_INFO_RECEIVED).
-- Class weapon use is Forever's table (ForeverDB "Trainers & weapon skills", checked 2026-10-17: it differs from Classic only in
-- that Rogues can use one-handed axes), kept in bis/build_quest_weapons.py; quests locked to the other faction are skipped.
-- Read-only: item info and equipped links, nothing written to the game.

local _, R2F = ...
local L = R2F.L

local QW = {}
R2F.QuestWeapons = QW

local function set(...)
  local t = {}
  for _, k in ipairs({ ... }) do t[k] = true end
  return t
end

-- Weapon kinds (the data's `kind`) each class can use. Forever's proficiencies; dual wield is not modelled. The table lives
-- in bis/build_quest_weapons.py (CLASS_USE) and comes with the data, so the site and the addon share one copy.
QW.USE = {}
for class, kinds in pairs((R2F.QuestWeaponData and R2F.QuestWeaponData.use) or {}) do QW.USE[class] = set(unpack(kinds)) end

function QW.CanUse(class, kind)
  local use = QW.USE[class or ""]
  return use ~= nil and use[kind] == true
end

-- "12–14" -> 12, 14; "~5" or "16" -> 5, 5; "Early", "Thu–Fri" -> nil.
function QW.LevelRange(text)
  if type(text) ~= "string" then return nil end
  local lo, hi
  for n in text:gmatch("%d+") do
    lo = lo or tonumber(n)
    hi = tonumber(n)
  end
  if not lo then return nil end
  return lo, hi
end

-- Is `zone` named in the step's title? "The Hall of Thanes" matches "Hall of Thanes — one clear".
function QW.ZoneInTitle(zone, title)
  if type(zone) ~= "string" or type(title) ~= "string" then return false end
  local z = zone:lower():gsub("^the ", "")
  return z ~= "" and title:lower():find(z, 1, true) ~= nil
end

local EQUIP_SLOT = {
  INVTYPE_WEAPON = "mainhand", INVTYPE_2HWEAPON = "mainhand", INVTYPE_WEAPONMAINHAND = "mainhand",
  INVTYPE_WEAPONOFFHAND = "offhand", INVTYPE_SHIELD = "offhand", INVTYPE_HOLDABLE = "offhand",
  INVTYPE_RANGED = "ranged", INVTYPE_RANGEDRIGHT = "ranged", INVTYPE_THROWN = "ranged",
}

-- "mainhand" | "offhand" | "ranged" for an item id, from the game's own equip location (nil when unknown).
function QW.SlotOf(id)
  local loc = select(4, R2F.Item.Instant(id))
  return loc and EQUIP_SLOT[loc] or nil
end

local COLOR = { [2] = "|cff1eff00", [3] = "|cff0070dd", [4] = "|cffa335ee" }
local function colored(name, q)
  return (COLOR[q] or "|cffffffff") .. name .. "|r"
end

local function playerClass()
  return R2F.playerClass or select(2, UnitClass("player"))
end

local function playerSide()
  local f = UnitFactionGroup and UnitFactionGroup("player")
  return f == "Alliance" and 1 or f == "Horde" and 2 or 0
end

-- Quest weapon rows for a step title and level range that this class can use and this faction can get.
function QW.Candidates(step, class, side)
  local data = R2F.QuestWeaponData
  local out = {}
  if not (data and data.items and step and step.t) then return out end
  local _, hi = QW.LevelRange(step.lvl)
  if not hi then return out end
  if step.t:lower():find("collect", 1, true) then return out end
  for _, r in ipairs(data.items) do
    local lvl, rside, kind, zone = r[4], r[7], r[3], r[6]
    if lvl <= hi and (rside == 0 or rside == side) and QW.CanUse(class, kind) and QW.ZoneInTitle(zone, step.t) then
      out[#out + 1] = { id = r[1], name = r[2], kind = kind, quest = r[5], zone = zone, q = r[8] }
    end
  end
  return out
end

-- Delta (BiZ score minus what is worn there), or nil when the item's stats are not loaded yet (and asks for them).
local function upgradeOf(id)
  local GS = R2F.GearScore
  local _, delta = GS.Compare("item:" .. id)
  if delta == nil and C_Item and C_Item.RequestLoadItemDataByID then pcall(C_Item.RequestLoadItemDataByID, id) end
  return delta
end

-- stepId -> { { slot =, text =, id =, delta = }, ... } for a plan: at most one line per weapon slot per step, only upgrades.
function QW.StepLines(planId)
  local out = {}
  if not (R2F.Plan and R2F.GearScore and R2F.Item) then return out end
  local class, side = playerClass(), playerSide()
  -- Scores are against your own gear and spec, so a previewed other class gets no weapon lines.
  local sel = R2F.Plan.Parse(planId)
  if not sel or sel.cls ~= class then return out end
  local specId = R2F.GearScore.SpecId()
  local route = specId and R2F.BiZ.RouteWeapons(specId, planId) or {}
  local spec = specId and R2F.BiZ.Spec(specId)
  local specName = spec and spec.name
  for _, st in ipairs(R2F.Plan.Steps(planId)) do
    local best = {}   -- slot -> { delta =, text =, id = }
    local function offer(slot, id, text, info)
      if not slot then return end
      local delta = upgradeOf(id)
      if not delta or delta <= 0 then return end
      if not best[slot] or delta > best[slot].delta then
        best[slot] = { slot = slot, id = id, delta = delta, text = text, specName = specName }
        for k, v in pairs(info or {}) do best[slot][k] = v end
      end
    end
    for _, m in ipairs(route[st.id] or {}) do
      local rankText = R2F.BiZ.RankName(m.rank) .. " " .. R2F.BiZ.SlotLabel(m.slot):lower()
      offer(m.slot, m.row.id, L.PLAN_WEAPON:format(R2F.BiZ.ColoredName(m.row.id, m.row.name), R2F.BiZ.RankName(m.rank),
        R2F.BiZ.SlotLabel(m.slot):lower()), { name = m.row.name, rankText = rankText, source = m.row.label })
    end
    for _, c in ipairs(QW.Candidates(st, class, side)) do
      offer(QW.SlotOf(c.id), c.id, L.PLAN_WEAPON_QUEST:format(colored(c.name, c.q), c.quest),
        { name = c.name, quest = c.quest, zone = c.zone })
    end
    local lines = {}
    for _, slot in ipairs({ "mainhand", "offhand", "ranged" }) do
      if best[slot] then lines[#lines + 1] = best[slot] end
    end
    if #lines > 0 then out[st.id] = lines end
  end
  return out
end
